    if (strcmp(info_type, "lang") == 0) {
        key = "Accept-Language";
    } else if (strcmp(info_type, "encoding") == 0) {
        key = "Accept-Encoding";
    } else if (strcmp(info_type, "cache") == 0) {
        key = "Cache-Control";
    } else {
        return header; // Invalid info_type, return original header
    }

    int index = find_header_index(header, key);

    if (index != -1) {
        // Key already exists, update the value
        if (strlen(info_content) < sizeof(header->entries[index].value)) {
            strcpy(header->entries[index].value, info_content);
        } else {
            return header; // Content too large, return original header
        }
    } else if (header->count < HEADER_SIZE) {
        // Key does not exist, add new entry
        if (strlen(info_content) < sizeof(header->entries[header->count].value)) {
            strncpy(header->entries[header->count].key, key, sizeof(header->entries[header->count].key) - 1);
